mapper.select:
SELECT wlh.id, wlh.user_id, wlh.shop_id, gsb.shop_name, wlh.wechat_id, gsb.shop_tel AS shopPhone, wlh.head_portrait, wlh.creata_time, wlh.state, wlh.cause, wlh.hoststate FROM ${database.prefix.userms}hou_base_wx_live_host wlh LEFT JOIN ${database.prefix.supplier}hou_shop_base gsb ON gsb.supplier_shop_id = wlh.shop_id where 1=1
and wlh.wechat_id = #{param.wechatId}
and gsb.shop_tel = #{param.shopPhone}
and gsb.shop_name = #{param.shopName}
and wlh.state = #{param.state}
order by creata_time desc
